    try db.exec(ManagedItem.create_table_sql);\n    var engine = TemplateEngine.init(init.gpa);\n    defer engine.deinit();\n    Admin.loadTemplates(&engine);\n    zypher.admin.setDb(&db);\n    zypher.admin.setEngine(&engine);\n    var sessions = SessionStore.init(init.gpa);\n    defer sessions.deinit();\n    zypher.middleware.session.setStore(&sessions);\n    zypher.middleware.session.setCookieConfig(.{ .secure = false }); // DEV_ONLY: set to true in production\n\n    const admin_routes = Admin.routes();\n    const app_routes = [_]Route{\n        Router.route(.get, \"/\", index),\n        Router.route(.get, \"/admin\", adminEntry),\n        Router.route(.get, \"/admin/login\", adminLoginInfo),\n        Router.route(.post, \"/admin/login\", adminLogin),\n    };\n    const routes = app_routes ++ admin_routes;\n    var router = Router.initFromSlice(&routes, notFound);\n    tl_db = &db;\n    tl_router = &router;\n\n    tl_io = init.io;\n    var app = zypher.core.App.init(init.gpa, .{ .host = \"127.0.0.1\", .port = parsePort(init) });\n    defer app.deinit();\n    app.middlewareHandler(runChain);\n    try app.listenAndServe(init.io);\n}\n\ntest \"api app imports zypher\" {\n    try std.testing.expect(@hasDecl(zypher, \"core\"));\n}\n" },
            .{ .path = "build.zig", .content = "const std = @import(\"std\");\n\npub fn build(b: *std.Build) void {\n    const target = b.standardTargetOptions(.{ .default_target = .{ .abi = .musl } });\n    const optimize = b.standardOptimizeOption(.{});\n    const zypher_root = b.option([]const u8, \"zypher-root\", \"Path to the Zypher source tree\") orelse \"../..\";\n    const sqlite_root = b.pathJoin(&.{ zypher_root, \"vendor/sqlite-amalgamation-3530000\" });\n\n    const sqlite3_mod = b.createModule(.{ .target = target, .optimize = optimize });\n    sqlite3_mod.addCSourceFiles(.{\n        .root = .{ .cwd_relative = sqlite_root },\n        .files = &.{\"sqlite3.c\"},\n        .flags = &.{ \"-std=c11\", \"-DSQLITE_THREADSAFE=0\", \"-DSQLITE_OMIT_LOAD_EXTENSION\" },\n    });\n    sqlite3_mod.addIncludePath(.{ .cwd_relative = sqlite_root });\n    sqlite3_mod.link_libc = true;\n    const sqlite3_lib = b.addLibrary(.{ .name = \"sqlite3\", .root_module = sqlite3_mod });\n\n    const zypher_mod = b.createModule(.{\n        .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ zypher_root, \"src/zypher.zig\" }) },\n        .target = target,\n        .optimize = optimize,\n    });\n    zypher_mod.linkLibrary(sqlite3_lib);\n    zypher_mod.addIncludePath(.{ .cwd_relative = sqlite_root });\n    zypher_mod.link_libc = true;\n\n    const exe = b.addExecutable(.{\n        .name = \"{{project_name}}\",\n        .root_module = b.createModule(.{\n            .root_source_file = b.path(\"src/main.zig\"),\n            .target = target,\n            .optimize = optimize,\n            .imports = &.{.{ .name = \"zypher\", .module = zypher_mod }},\n        }),\n    });\n    b.installArtifact(exe);\n    const run_cmd = b.addRunArtifact(exe);\n    run_cmd.step.dependOn(b.getInstallStep());\n    run_cmd.addPassthruArgs();\n    b.step(\"run\", \"Run the app\").dependOn(&run_cmd.step);\n    const app_docs = b.addTest(.{ .root_module = exe.root_module });\n    const install_docs = b.addInstallDirectory(.{\n        .source_dir = app_docs.getEmittedDocs(),\n        .install_dir = .prefix,\n        .install_subdir = \"docs\",\n    });\n    b.step(\"doc\", \"Generate app documentation\").dependOn(&install_docs.step);\n\n    b.step(\"test\", \"Run app tests\").dependOn(&b.addRunArtifact(b.addTest(.{ .root_module = exe.root_module })).step);\n}\n" },
