            .{ .path = "src/application/resource_service.zig", .content = "const domain = @import(\"../domain/resource.zig\");\n\npub fn listResources() []const domain.Resource {\n    return &.{.{ .id = 1, .name = \"{{project_name}}\" }};\n}\n" },
